usage:
import { AgentStatusPill } from "@/components/design-for-ai/agent-status-pill";

<AgentStatusPill
  agent="Fixer"
  state={run.status}               // "idle" | "running" | "waiting" | "error" | "done"
  since={run.startedAt}            // epoch ms; the clock ticks until `until` is set
  until={run.finishedAt}
  summary="Fixer wants to apply one pending migration to staging."
  command="pnpm prisma migrate deploy"
  actions={[
    { label: "Deny", onSelect: () => run.deny() },
    { label: "Approve", onSelect: () => run.approve(), primary: true },
  ]}
/>

// In a list row, smaller and without the panel copy:
<AgentStatusPill size="sm" state="running" since={startedAt} />

// The panel is positioned inside the pill's own wrapper (no portal). Inside a
// clipping container, lift it to document.body with your own portal or give
// the row `position: relative` and a z-index while it is open.
